object CommonMessagesCodec {

    const val EXI_HEADER: Byte = 0x80.toByte()

    /** Generous upper bound; encode() returns a right-sized copy. */
    private const val MAX_MESSAGE_BYTES = 65536

    fun encode(msg: SessionSetupReq): ByteArray {
        val buf = ByteArray(MAX_MESSAGE_BYTES)
        buf[0] = EXI_HEADER
        val w = BitWriter(buf, 1)
        w.writeBits(35u, 6)   // document element selector
        encodeSessionSetupReq(w, msg)
        w.alignToByte()
        return buf.copyOf(1 + w.bytesWritten)
    }

