    fun decodeAny(src: ByteArray): Any {
        require(src.isNotEmpty() && src[0] == EXI_HEADER) { "Invalid EXI header." }
        val r = BitReader(src, 1)
        return when (val sel = r.readBits(6)) {
            35u -> decodeSessionSetupReq(r)
            36u -> decodeSessionSetupRes(r)
            2u -> decodeAuthorizationSetupReq(r)
            3u -> decodeAuthorizationSetupRes(r)
            0u -> decodeAuthorizationReq(r)
            1u -> decodeAuthorizationRes(r)
            31u -> decodeServiceDiscoveryReq(r)
            32u -> decodeServiceDiscoveryRes(r)
            29u -> decodeServiceDetailReq(r)
            30u -> decodeServiceDetailRes(r)
            33u -> decodeServiceSelectionReq(r)
            34u -> decodeServiceSelectionRes(r)
            27u -> decodeScheduleExchangeReq(r)
            28u -> decodeScheduleExchangeRes(r)
            21u -> decodePowerDeliveryReq(r)
            22u -> decodePowerDeliveryRes(r)
            16u -> decodeMeteringConfirmationReq(r)
            17u -> decodeMeteringConfirmationRes(r)
            37u -> decodeSessionStopReq(r)
            38u -> decodeSessionStopRes(r)
            7u -> decodeCertificateInstallationReq(r)
            8u -> decodeCertificateInstallationRes(r)
            49u -> decodeVehicleCheckInReq(r)
            50u -> decodeVehicleCheckInRes(r)
            51u -> decodeVehicleCheckOutReq(r)
            52u -> decodeVehicleCheckOutRes(r)
            45u -> decodeSignedInstallationData(r)
            46u -> decodeSignedMeteringData(r)
            else -> throw IllegalArgumentException("Unknown document index $sel.")
        }
    }

    private fun encodeSessionSetupReqType(w: BitWriter, msg: SessionSetupReqType) {
        w.writeBits(0u, 1)   // SE
        encodeMessageHeaderType(w, msg.header)
        w.writeBits(0u, 1)   // SE
        w.writeBits(0u, 1)   // value-start
        ExiPrimitives.writeStringValue(w, msg.eVCCID)
        w.writeBits(0u, 1)   // child EE
        w.writeBits(0u, 1)   // element EE
    }

    private fun decodeSessionSetupReqType(r: BitReader): SessionSetupReqType {
        r.readBits(1)   // SE
        val _header = decodeMessageHeaderType(r)
        r.readBits(1)   // SE
        r.readBits(1)   // value-start
        val _eVCCID = ExiPrimitives.readStringValue(r)
        r.readBits(1)   // child EE
        r.readBits(1)   // element EE
        return SessionSetupReqType(_header, _eVCCID)
    }

    private fun encodeSessionSetupResType(w: BitWriter, msg: SessionSetupResType) {
        w.writeBits(0u, 1)   // SE
        encodeMessageHeaderType(w, msg.header)
        w.writeBits(0u, 1)   // SE
        w.writeBits(0u, 1)   // value-start
        w.writeBits(msg.responseCode.ordinal.toUInt(), 6)
        w.writeBits(0u, 1)   // child EE
        w.writeBits(0u, 1)   // SE
        w.writeBits(0u, 1)   // value-start
        ExiPrimitives.writeStringValue(w, msg.eVSEID)
        w.writeBits(0u, 1)   // child EE
        w.writeBits(0u, 1)   // element EE
    }

    private fun decodeSessionSetupResType(r: BitReader): SessionSetupResType {
        r.readBits(1)   // SE
        val _header = decodeMessageHeaderType(r)
        r.readBits(1)   // SE
        r.readBits(1)   // value-start
        val _responseCode = ResponseCode.entries[r.readBits(6).toInt()]
        r.readBits(1)   // child EE
        r.readBits(1)   // SE
        r.readBits(1)   // value-start
        val _eVSEID = ExiPrimitives.readStringValue(r)
        r.readBits(1)   // child EE
        r.readBits(1)   // element EE
        return SessionSetupResType(_header, _responseCode, _eVSEID)
    }

    private fun encodeAuthorizationSetupReqType(w: BitWriter, msg: AuthorizationSetupReqType) {
        w.writeBits(0u, 1)   // SE
        encodeMessageHeaderType(w, msg.header)
        w.writeBits(0u, 1)   // element EE
    }

    private fun decodeAuthorizationSetupReqType(r: BitReader): AuthorizationSetupReqType {
        r.readBits(1)   // SE
        val _header = decodeMessageHeaderType(r)
        r.readBits(1)   // element EE
        return AuthorizationSetupReqType(_header)
    }

    private fun encodeAuthorizationSetupResType(w: BitWriter, msg: AuthorizationSetupResType) {
        w.writeBits(0u, 1)   // SE
        encodeMessageHeaderType(w, msg.header)
        w.writeBits(0u, 1)   // SE
        w.writeBits(0u, 1)   // value-start
        w.writeBits(msg.responseCode.ordinal.toUInt(), 6)
        w.writeBits(0u, 1)   // child EE
        require(msg.authorizationServices.size in 1..2) { "list size out of schema range" }
        w.writeBits(0u, 1)   // SE(AuthorizationServices)
        w.writeBits(0u, 1)   // value-start
        w.writeBits(msg.authorizationServices[0].ordinal.toUInt(), 1)
        w.writeBits(0u, 1)   // child EE
        if (msg.authorizationServices.size > 1) {
            w.writeBits(0u, 2)   // AuthorizationServices (loop)
            w.writeBits(0u, 1)   // value-start
            w.writeBits(msg.authorizationServices[1].ordinal.toUInt(), 1)
            w.writeBits(0u, 1)   // child EE
            w.writeBits(0u, 1)   // CertificateInstallationService
            w.writeBits(0u, 1)   // value-start
            w.writeBits(if (msg.certificateInstallationService) 1u else 0u, 1)
            w.writeBits(0u, 1)   // child EE
        } else {
            w.writeBits(1u, 2)   // CertificateInstallationService
            w.writeBits(0u, 1)   // value-start
            w.writeBits(if (msg.certificateInstallationService) 1u else 0u, 1)
            w.writeBits(0u, 1)   // child EE
        }
        if (msg.eIM_ASResAuthorizationMode != null) {
            w.writeBits(0u, 2)   // EIM_ASResAuthorizationMode
            encodeEIM_ASResAuthorizationModeType(w, msg.eIM_ASResAuthorizationMode!!)
        } else if (msg.pnC_ASResAuthorizationMode != null) {
            w.writeBits(1u, 2)   // PnC_ASResAuthorizationMode
            encodePnC_ASResAuthorizationModeType(w, msg.pnC_ASResAuthorizationMode!!)
        } else {
            throw IllegalArgumentException("no choice alternative set")
        }
        w.writeBits(0u, 1)   // element EE
    }

    private fun decodeAuthorizationSetupResType(r: BitReader): AuthorizationSetupResType {
        r.readBits(1)   // SE
        val _header = decodeMessageHeaderType(r)
        r.readBits(1)   // SE
        r.readBits(1)   // value-start
        val _responseCode = ResponseCode.entries[r.readBits(6).toInt()]
        r.readBits(1)   // child EE
        val authorizationServicesList = ArrayList<Authorization>()
        r.readBits(1)   // SE(AuthorizationServices) first
        r.readBits(1)   // value-start
        val authorizationServicesListFirst = Authorization.entries[r.readBits(1).toInt()]
        r.readBits(1)   // child EE
        authorizationServicesList.add(authorizationServicesListFirst)
        var _certificateInstallationService: Boolean? = null
        when (r.readBits(2)) {
            0u -> {   // AuthorizationServices (loop)
                r.readBits(1)   // value-start
                val authorizationServicesListNext = Authorization.entries[r.readBits(1).toInt()]
                r.readBits(1)   // child EE
                authorizationServicesList.add(authorizationServicesListNext)
                when (r.readBits(1)) {
                    0u -> {   // CertificateInstallationService
                        r.readBits(1)   // value-start
                        _certificateInstallationService = r.readBits(1).toInt() != 0
                        r.readBits(1)   // child EE
                    }
                    else -> throw IllegalArgumentException("invalid event code")
                }
            }
            1u -> {   // CertificateInstallationService
                r.readBits(1)   // value-start
                _certificateInstallationService = r.readBits(1).toInt() != 0
                r.readBits(1)   // child EE
            }
            else -> throw IllegalArgumentException("invalid event code")
        }
        var _eIM_ASResAuthorizationMode: EIM_ASResAuthorizationModeType? = null
        var _pnC_ASResAuthorizationMode: PnC_ASResAuthorizationModeType? = null
        when (r.readBits(2)) {
            0u -> {   // EIM_ASResAuthorizationMode
                _eIM_ASResAuthorizationMode = decodeEIM_ASResAuthorizationModeType(r)
            }
            1u -> {   // PnC_ASResAuthorizationMode
                _pnC_ASResAuthorizationMode = decodePnC_ASResAuthorizationModeType(r)
            }
            else -> throw IllegalArgumentException("unknown choice event code")
        }
        r.readBits(1)   // element EE
        return AuthorizationSetupResType(_header, _responseCode, authorizationServicesList, _certificateInstallationService!!, _eIM_ASResAuthorizationMode, _pnC_ASResAuthorizationMode)
    }

    private fun encodeAuthorizationReqType(w: BitWriter, msg: AuthorizationReqType) {
        w.writeBits(0u, 1)   // SE
        encodeMessageHeaderType(w, msg.header)
        w.writeBits(0u, 1)   // SE
        w.writeBits(0u, 1)   // value-start
        w.writeBits(msg.selectedAuthorizationService.ordinal.toUInt(), 1)
        w.writeBits(0u, 1)   // child EE
        if (msg.eIM_AReqAuthorizationMode != null) {
            w.writeBits(0u, 2)   // EIM_AReqAuthorizationMode
            encodeEIM_AReqAuthorizationModeType(w, msg.eIM_AReqAuthorizationMode!!)
        } else if (msg.pnC_AReqAuthorizationMode != null) {
            w.writeBits(1u, 2)   // PnC_AReqAuthorizationMode
            encodePnC_AReqAuthorizationModeType(w, msg.pnC_AReqAuthorizationMode!!)
        } else {
            throw IllegalArgumentException("no choice alternative set")
        }
        w.writeBits(0u, 1)   // element EE
    }

    private fun decodeAuthorizationReqType(r: BitReader): AuthorizationReqType {
        r.readBits(1)   // SE
        val _header = decodeMessageHeaderType(r)
        r.readBits(1)   // SE
        r.readBits(1)   // value-start
        val _selectedAuthorizationService = Authorization.entries[r.readBits(1).toInt()]
        r.readBits(1)   // child EE
        var _eIM_AReqAuthorizationMode: EIM_AReqAuthorizationModeType? = null
        var _pnC_AReqAuthorizationMode: PnC_AReqAuthorizationModeType? = null
        when (r.readBits(2)) {
            0u -> {   // EIM_AReqAuthorizationMode
                _eIM_AReqAuthorizationMode = decodeEIM_AReqAuthorizationModeType(r)
            }
            1u -> {   // PnC_AReqAuthorizationMode
                _pnC_AReqAuthorizationMode = decodePnC_AReqAuthorizationModeType(r)
            }
            else -> throw IllegalArgumentException("unknown choice event code")
        }
        r.readBits(1)   // element EE
        return AuthorizationReqType(_header, _selectedAuthorizationService, _eIM_AReqAuthorizationMode, _pnC_AReqAuthorizationMode)
    }

    private fun encodeAuthorizationResType(w: BitWriter, msg: AuthorizationResType) {
        w.writeBits(0u, 1)   // SE
        encodeMessageHeaderType(w, msg.header)
        w.writeBits(0u, 1)   // SE
        w.writeBits(0u, 1)   // value-start
        w.writeBits(msg.responseCode.ordinal.toUInt(), 6)
        w.writeBits(0u, 1)   // child EE
        w.writeBits(0u, 1)   // SE
        w.writeBits(0u, 1)   // value-start
        w.writeBits(msg.eVSEProcessing.ordinal.toUInt(), 2)
        w.writeBits(0u, 1)   // child EE
        w.writeBits(0u, 1)   // element EE
    }

    private fun decodeAuthorizationResType(r: BitReader): AuthorizationResType {
        r.readBits(1)   // SE
        val _header = decodeMessageHeaderType(r)
        r.readBits(1)   // SE
        r.readBits(1)   // value-start
        val _responseCode = ResponseCode.entries[r.readBits(6).toInt()]
        r.readBits(1)   // child EE
        r.readBits(1)   // SE
        r.readBits(1)   // value-start
        val _eVSEProcessing = Processing.entries[r.readBits(2).toInt()]
        r.readBits(1)   // child EE
        r.readBits(1)   // element EE
        return AuthorizationResType(_header, _responseCode, _eVSEProcessing)
    }

    private fun encodeServiceDiscoveryReqType(w: BitWriter, msg: ServiceDiscoveryReqType) {
        w.writeBits(0u, 1)   // SE
        encodeMessageHeaderType(w, msg.header)
        var st0 = 0
        var done0 = false
        while (!done0) {
            when (st0) {
                0 -> {
                    if (msg.supportedServiceIDs != null) {
                        w.writeBits(0u, 2)   // SupportedServiceIDs
                        encodeServiceIDListType(w, msg.supportedServiceIDs!!)
                        st0 = 1
                    } else {
                        w.writeBits(1u, 2)   // element EE
                        done0 = true
                    }
                }
                1 -> {
                    w.writeBits(0u, 1)   // element EE
                    done0 = true
                }
            }
        }
    }

    private fun decodeServiceDiscoveryReqType(r: BitReader): ServiceDiscoveryReqType {
        r.readBits(1)   // SE
