        while (!done71) {
            when (st71) {
                0 -> {
                    when (r.readBits(4)) {
                        0u -> {
                            r.readBits(1)   // value-start
                            _presentSOC = r.readBits(7).toByte()
                            r.readBits(1)   // child EE
                            st71 = 1
                        }
                        1u -> {
                            r.readBits(1)   // value-start
                            _minimumSOC = r.readBits(7).toByte()
                            r.readBits(1)   // child EE
                            st71 = 2
                        }
                        2u -> {
                            r.readBits(1)   // value-start
                            _targetSOC = r.readBits(7).toByte()
                            r.readBits(1)   // child EE
                            st71 = 3
                        }
                        3u -> {
                            r.readBits(1)   // value-start
