                            r.readBits(1)   // child EE
                            st71 = 4
                        }
                        4u -> {
                            r.readBits(1)   // value-start
                            _remainingTimeToMinimumSOC = ExiPrimitives.readUnsignedInteger(r).toUInt()
                            r.readBits(1)   // child EE
                            st71 = 5
                        }
                        5u -> {
                            r.readBits(1)   // value-start
                            _remainingTimeToTargetSOC = ExiPrimitives.readUnsignedInteger(r).toUInt()
                            r.readBits(1)   // child EE
                            st71 = 6
