    private fun encodeVehicleCheckOutRes(w: BitWriter, msg: VehicleCheckOutRes) {
        w.writeBits(0u, 1)   // SE
        encodeMessageHeaderType(w, msg.header)
        w.writeBits(0u, 1)   // SE
        w.writeBits(0u, 1)   // value-start
        w.writeBits(msg.responseCode.ordinal.toUInt(), 6)
        w.writeBits(0u, 1)   // child EE
        w.writeBits(0u, 1)   // SE
        w.writeBits(0u, 1)   // value-start
        w.writeBits(msg.eVSECheckOutStatus.ordinal.toUInt(), 1)
        w.writeBits(0u, 1)   // child EE
        w.writeBits(0u, 1)   // element EE
    }

    private fun decodeVehicleCheckOutRes(r: BitReader): VehicleCheckOutRes {
        r.readBits(1)   // SE
        val _header = decodeMessageHeaderType(r)
        r.readBits(1)   // SE
        r.readBits(1)   // value-start
        val _responseCode = ResponseCode.entries[r.readBits(6).toInt()]
        r.readBits(1)   // child EE
        r.readBits(1)   // SE
        r.readBits(1)   // value-start
        val _eVSECheckOutStatus = EvseCheckOutStatus.entries[r.readBits(1).toInt()]
        r.readBits(1)   // child EE
        r.readBits(1)   // element EE
        return VehicleCheckOutRes(_header, _responseCode, _eVSECheckOutStatus)
    }

    private fun encodeSignedInstallationData(w: BitWriter, msg: SignedInstallationData) {
        w.writeBits(0u, 1)   // AT(required attribute)
        ExiPrimitives.writeStringValue(w, msg.id)
        w.writeBits(0u, 1)   // SE
        encodeContractCertificateChainType(w, msg.contractCertificateChain)
        w.writeBits(0u, 1)   // SE
        w.writeBits(0u, 1)   // value-start
        w.writeBits(msg.eCDHCurve.ordinal.toUInt(), 1)
        w.writeBits(0u, 1)   // child EE
        w.writeBits(0u, 1)   // SE
        w.writeBits(0u, 1)   // value-start
        ExiPrimitives.writeBinary(w, msg.dHPublicKey)
        w.writeBits(0u, 1)   // child EE
        if (msg.sECP521_EncryptedPrivateKey != null) {
            w.writeBits(0u, 2)   // SECP521_EncryptedPrivateKey
            w.writeBits(0u, 1)   // value-start
            ExiPrimitives.writeBinary(w, msg.sECP521_EncryptedPrivateKey!!)
            w.writeBits(0u, 1)   // child EE
        } else if (msg.x448_EncryptedPrivateKey != null) {
            w.writeBits(1u, 2)   // X448_EncryptedPrivateKey
            w.writeBits(0u, 1)   // value-start
            ExiPrimitives.writeBinary(w, msg.x448_EncryptedPrivateKey!!)
            w.writeBits(0u, 1)   // child EE
        } else if (msg.tPM_EncryptedPrivateKey != null) {
            w.writeBits(2u, 2)   // TPM_EncryptedPrivateKey
            w.writeBits(0u, 1)   // value-start
            ExiPrimitives.writeBinary(w, msg.tPM_EncryptedPrivateKey!!)
            w.writeBits(0u, 1)   // child EE
        } else {
            throw IllegalArgumentException("no choice alternative set")
        }
        w.writeBits(0u, 1)   // element EE
    }

    private fun decodeSignedInstallationData(r: BitReader): SignedInstallationData {
        r.readBits(1)   // AT(required attribute)
        val _id = ExiPrimitives.readStringValue(r)
        r.readBits(1)   // SE
        val _contractCertificateChain = decodeContractCertificateChainType(r)
        r.readBits(1)   // SE
        r.readBits(1)   // value-start
        val _eCDHCurve = EcdhCurve.entries[r.readBits(1).toInt()]
        r.readBits(1)   // child EE
        r.readBits(1)   // SE
        r.readBits(1)   // value-start
        val _dHPublicKey = ExiPrimitives.readBinary(r)
        r.readBits(1)   // child EE
        var _sECP521_EncryptedPrivateKey: ByteArray? = null
        var _x448_EncryptedPrivateKey: ByteArray? = null
        var _tPM_EncryptedPrivateKey: ByteArray? = null
        when (r.readBits(2)) {
            0u -> {   // SECP521_EncryptedPrivateKey
                r.readBits(1)   // value-start
                _sECP521_EncryptedPrivateKey = ExiPrimitives.readBinary(r)
                r.readBits(1)   // child EE
            }
            1u -> {   // X448_EncryptedPrivateKey
                r.readBits(1)   // value-start
                _x448_EncryptedPrivateKey = ExiPrimitives.readBinary(r)
                r.readBits(1)   // child EE
            }
            2u -> {   // TPM_EncryptedPrivateKey
                r.readBits(1)   // value-start
                _tPM_EncryptedPrivateKey = ExiPrimitives.readBinary(r)
                r.readBits(1)   // child EE
            }
            else -> throw IllegalArgumentException("unknown choice event code")
        }
        r.readBits(1)   // element EE
        return SignedInstallationData(_id, _contractCertificateChain, _eCDHCurve, _dHPublicKey, _sECP521_EncryptedPrivateKey, _x448_EncryptedPrivateKey, _tPM_EncryptedPrivateKey)
    }

    private fun encodeSignedMeteringData(w: BitWriter, msg: SignedMeteringData) {
        w.writeBits(0u, 1)   // AT(required attribute)
        ExiPrimitives.writeStringValue(w, msg.id)
        w.writeBits(0u, 1)   // SE
        w.writeBits(0u, 1)   // value-start
        ExiPrimitives.writeBinary(w, msg.sessionID)
        w.writeBits(0u, 1)   // child EE
        w.writeBits(0u, 1)   // SE
        encodeMeterInfoType(w, msg.meterInfo)
        var st114 = 0
        var done114 = false
        while (!done114) {
            when (st114) {
                0 -> {
                    if (msg.receipt != null) {
                        w.writeBits(0u, 2)   // Receipt
                        encodeReceiptType(w, msg.receipt!!)
                        st114 = 1
                    } else if (msg.dynamic_SMDTControlMode != null) {
                        w.writeBits(1u, 2)   // Dynamic_SMDTControlMode
                        encodeDynamic_SMDTControlModeType(w, msg.dynamic_SMDTControlMode!!)
                        done114 = true
                    } else if (msg.scheduled_SMDTControlMode != null) {
                        w.writeBits(2u, 2)   // Scheduled_SMDTControlMode
                        encodeScheduled_SMDTControlModeType(w, msg.scheduled_SMDTControlMode!!)
                        done114 = true
                    } else {
                        throw IllegalArgumentException("no value set for \$InlineChoice")
                    }
                }
                1 -> {
                    if (msg.dynamic_SMDTControlMode != null) {
                        w.writeBits(0u, 2)   // Dynamic_SMDTControlMode
                        encodeDynamic_SMDTControlModeType(w, msg.dynamic_SMDTControlMode!!)
                        done114 = true
                    } else if (msg.scheduled_SMDTControlMode != null) {
                        w.writeBits(1u, 2)   // Scheduled_SMDTControlMode
                        encodeScheduled_SMDTControlModeType(w, msg.scheduled_SMDTControlMode!!)
                        done114 = true
                    } else {
                        throw IllegalArgumentException("no value set for \$InlineChoice")
                    }
                }
            }
        }
        w.writeBits(0u, 1)   // element EE
    }

    private fun decodeSignedMeteringData(r: BitReader): SignedMeteringData {
        r.readBits(1)   // AT(required attribute)
        val _id = ExiPrimitives.readStringValue(r)
        r.readBits(1)   // SE
        r.readBits(1)   // value-start
        val _sessionID = ExiPrimitives.readBinary(r)
        r.readBits(1)   // child EE
        r.readBits(1)   // SE
        val _meterInfo = decodeMeterInfoType(r)
        var _receipt: ReceiptType? = null
        var _dynamic_SMDTControlMode: Dynamic_SMDTControlModeType? = null
        var _scheduled_SMDTControlMode: Scheduled_SMDTControlModeType? = null
        var st115 = 0
        var done115 = false
        while (!done115) {
            when (st115) {
                0 -> {
                    when (r.readBits(2)) {
                        0u -> {
                            _receipt = decodeReceiptType(r)
                            st115 = 1
                        }
                        1u -> {   // Dynamic_SMDTControlMode
                            _dynamic_SMDTControlMode = decodeDynamic_SMDTControlModeType(r)
                            done115 = true
                        }
                        2u -> {   // Scheduled_SMDTControlMode
                            _scheduled_SMDTControlMode = decodeScheduled_SMDTControlModeType(r)
                            done115 = true
                        }
                        else -> throw IllegalArgumentException("invalid optional-run event code")
                    }
                }
                1 -> {
                    when (r.readBits(2)) {
                        0u -> {   // Dynamic_SMDTControlMode
                            _dynamic_SMDTControlMode = decodeDynamic_SMDTControlModeType(r)
                            done115 = true
                        }
                        1u -> {   // Scheduled_SMDTControlMode
                            _scheduled_SMDTControlMode = decodeScheduled_SMDTControlModeType(r)
                            done115 = true
                        }
                        else -> throw IllegalArgumentException("invalid optional-run event code")
                    }
                }
            }
        }
        r.readBits(1)   // element EE
        return SignedMeteringData(_id, _sessionID, _meterInfo, _receipt, _dynamic_SMDTControlMode, _scheduled_SMDTControlMode)
    }

}
